void InitList(LinkNode*&amp; L)   //初始化链表线性表
{
    L = (LinkNode*)malloc(sizeof(LinkNode));
    L-&gt;next = NULL;     //创建头节点，将其next域置为NULL
}

void CreateListR(LinkNode*&amp; L, ElemType a[],int n)//链表尾插法
{
    LinkNode* s,*r;
    L=(LinkNode*)malloc(sizeof(LinkNode));//分配空间,创建头节点
    r = L; //r始终指向尾节点，初始时指向头节点
    for (int i = 0; i &lt; n; i++)        //循环建立数据节点
    {
        s = (LinkNode*)malloc(sizeof(LinkNode));//分配空间
        s-&gt;data = a[i];    //创建数据节点s
        r-&gt;next = s;       //将节点s插入到节点r之后
        r = s;
    }
    r-&gt;next = NULL; //将尾节点的next域置为NULL
}

void CreateListF(LinkNode*&amp; L, ElemType a[], int n)//链表头插法
{
    LinkNode* s;
    L = (LinkNode*)malloc(sizeof(LinkNode));      //分配空间
    L-&gt;next = NULL;                               //创建头节点，将其next域设置为NULL
    for (int i = 0; i &lt; n; i++)                   //循环建立数据节点s
    {
        s = (LinkNode*)malloc(sizeof(LinkNode));  //分配空间
        s-&gt;data = a[i];                           //创建数据节点s
        s-&gt;next = L-&gt;next;                        //将节点s插入原首节点前，头节点后
        L-&gt;next = s;
    }
}  

void DestroyList(LinkNode *&amp;L)   //销毁链表形线性表
{
    LinkNode *pre=L,*p=L-&gt;next;  //pre指向节点p的前驱节点
    while(p!=NULL)               //遍历单链表L
    {                 
        free(p);                //释放pre节点
        pre=p;                  //pre,p同步后移一个节点
        p=pre-&gt;next;
    }
    free(pre);                 //循环结束时p为NULL，pre指向尾节点，释放它
}

bool ListEmpty(LinkNode *L)  //判断链表形线性表是否为空表
{
    return (L-&gt;next==NULL);
}

int ListLength(LinkNode *L)  //求链表形线性表的长度
{
    int n=0;
    LinkNode *p=L;          //p指向头节点，n置为0（即头节点的序号为0）
    while(p-&gt;next!=NULL)
    {
        n++;
        p=p-&gt;next;
    }
    return (n);           //循环结束，p指向尾节点，其序号n为节点个数
}

void DispList(LinkNode *L)  //输出链表形线性表
{
    LinkNode *p=L-&gt;next;    //p指向首节点
    while(p!=NULL)          //p不为NULL,输出p节点的data域
    {
        printf(&quot;%d&quot;,p-&gt;data);
        p=p-&gt;next;         //p指向下一个节点
    }
    printf(&quot;\n&quot;);
}

bool GetElem(LinkNode *L,int i,ElemType &amp;e)  //按序号求链表形顺序表中元素
{
    int j=0;
    LinkNode *p=L;         //p指向头节点，j置为0（即头节点的序号是0）
    if(i&lt;=0) return false; //i错误返回假
    while(j&lt;i&amp;&amp;p!=NULL)    //查找第i个节点p
    {
        j++;
        p=p-&gt;next;
    }
    if(p==NULL)           //不存在第i个数据节点，返回false
    return false;
    else                  //存在第i个数据节点，返回true
    {
        e=p-&gt;data;
        return true;
    }
}

int LocateElem(LinkNode *L,ElemType e)  //按元素查找链表形顺序表中的元素
{
    int i=1;
    LinkNode *p=L-&gt;next;       //p指向首节点，i置为1（即首节点的序号是1）
    while(p!=NULL&amp;&amp;p-&gt;data!=e)//查找data值为e的节点，其序号是i
    {
        p=p-&gt;next;
        i++;
    }
    if(p==NULL)               //不存在值为e的节点，返回0
    return (0);
    else                      //存在值为e的节点，返回其逻辑序号i
    return (i);
}

bool ListInsert(LinkNode *&amp; L,int i,ElemType e)   //在链表形顺序表中第i个位置插入数据元素e
{
    int j=0;
    LinkNode *p=L,*s;  //p指向头节点，j置为0（即头节点的序号为0）
    if(i&lt;=0)return false;  //i错误返回false
    while(j&lt;i-1&amp;&amp;p!=NULL)  //查找第i-1个节点
    {
        j++;
        p=p-&gt;next;
    }
    if(p==NULL)  //未找到第i-1个节点p，返回false
    return false;
    else        //找到第i-1个节点p，插入新节点并返回true
    {
        s=(LinkNode*)malloc(sizeof(LinkNode));
        s-&gt;data=e; //创建新节点s,将其data域置为e
        s-&gt;next=p-&gt;next;  //将节点s插入到节点p之后
        p-&gt;next=s;
        return true;
    }
}

bool ListDelete(LinkNode *&amp; L,int i,ElemType &amp; e)  //在链表形顺序表中删除第i个数据元素，并且把值赋给e
{
    int j=0;
    LinkNode *p=L,*q;  //p指向头节点，j置为0（即头节点的序号为0）
    if(i&lt;=0)return false;  //i错误返回false
    while(j&lt;i-1&amp;&amp;p!=NULL)  //查找第i-1个节点p
    {
        j++;
        p=p-&gt;next;
    } 
    if(p==NULL)  //未找到第i-1个节点p，返回false
    return false;
    else        //找到第i-1个节点p
    { 
        q=p-&gt;next;  //q指向第i个节点
        if(q==NULL)  //若不存在第i个节点，返回false
        return false;
        e=q-&gt;data;
        p-&gt;next=q-&gt;next;  //从单链表删除q节点
        free(q);  //释放q节点
        return true;  //返回true表示成功删除第i个节点
    }

}

代码小记/proteus_51实验小记.content:
﻿
实验六))
元件
6116：2KB RAM，地址线 A0A10（11 根）、数据线 D0D7、控制端{WE}（写）、{OE}（读）、{CS}（片选）。
2716：2KB EPROM，地址线 A0A10、数据线 D0D7、控制端{OE}（读）、{CE}（片选）。
AT89C51：P0 口（地址 / 数据复用，需接锁存器 74HC573）、P2 口（高 8 位地址）。
连线
给 6116 和 2716 分配互不重叠的地址空间
eg:以 “6116 地址：0x20000x27FF；2716 地址：0x30000x37FF”


地址锁存  （P0 口→74HC573）：
AT89C51 的ALE（地址锁存允许）接 74HC573 的LE（锁存使能）；
AT89C51 的P0.0P0.7接 74HC573 的D0D7；
74HC573 的Q0Q7接 6116 的A0A7 + 2716 的A0~A7。



高 8 位地址（P2 口）：
AT89C51 的P2.0P2.2接 6116 的A8A10 + 2716 的A8A10
（因为 6116/2716 是 2KB，需要 11 根地址线，A0A10）


6116 的{~CS}：用 P2.5 控制（P2.5=0 时选中），所以P2.5接 6116 的{~CS}；
2716 的{~CE}：用 P2.6 控制（P2.6=0 时选中），所以P2.6接 2716 的{~CE}。



数据总线（P0 口）：
AT89C51 的P0.0P0.7接 6116 的D0D7 + 2716 的D0~D7。



控制端
6116 的{~WE}接 AT89C51 的WR（写控制）；
6116 的{~OE}接 AT89C51 的RD（读控制）；
2716 的{~OE}接 AT89C51 的RD（读控制）。

#include &lt;reg51.h&gt;
#include &lt;absacc.h&gt;  // 包含XBYTE、CODE等宏

// 定义6116的写地址（外部数据区）和读地址（外部程序区）
#define RAM_WRITE_ADDR 0x2030  // 6116写地址起始：0x2030
#define RAM_READ_ADDR  0x3030  // 6116读地址起始（当作程序区）

void main(void) {
    unsigned char i;
    unsigned char *ram_write_ptr = (unsigned char *)RAM_WRITE_ADDR;
    char code *ram_read_ptr = (char code *)RAM_READ_ADDR;  // MOVC方式用code指针

    // 1. 向6116的0x2030~0x2040写数据1、2…
    for(i=0; i&lt;=0x10; i++){  // 从30H到40H共17个地址（0x40-0x30+1=17）
        ram_write_ptr[i] = i + 1;  // 写1、2…17
    }

    // 2. 用MOVC方式读6116的0x3030~0x3040数据（可在仿真中看变量值）
    unsigned char read_data;
    for(i=0; i&lt;=0x10; i++){
        read_data = ram_read_ptr[i];  // MOVC指令读程序区
        // 这里可以加串口打印等操作，方便观察结果
    }

    while(1);  // 程序停在这里
}
2716是无仿真模型，替换成2732，就地址线多一根，其他一样  )

没辙，最后换成MOVEX读取写入



