}

void LCD_WriteData(unsigned char dat) {
    LCD_RS = 1; // 数据模式
    LCD_RW = 0;
    LCD_E = 0;
    LCD_DATA = dat;
    LCD_E = 1;
    LCD_Delay(1);
    LCD_E = 0;
    LCD_Delay(2);
}
标准LCD1602写操作，先设置RS/RW，然后送数据，最后产生E脉冲。
LCD初始化
void LCD_Init(void) {
    LCD_Delay(15);
    LCD_WriteCmd(0x38); // 8位数据，2行显示，5x7点阵
    LCD_Delay(5);
    LCD_WriteCmd(0x38);
    LCD_Delay(1);
    LCD_WriteCmd(0x38);
    LCD_WriteCmd(0x08); // 显示关闭
    LCD_WriteCmd(0x01); // 清屏
    LCD_WriteCmd(0x06); // 光标移动设置：写入后光标右移
    LCD_WriteCmd(0x0C); // 显示开，光标关，闪烁关
}
按照LCD1602手册要求的上电初始化序列。
光标设置与显示函数
void LCD_SetCursor(unsigned char x, unsigned char y) {
    unsigned char addr;
    if(y == 0) addr = 0x80 + x;
    else addr = 0xC0 + x;
    LCD_WriteCmd(addr);
}

void LCD_ShowChar(unsigned char x, unsigned char y, unsigned char ch) {
    LCD_SetCursor(x, y);
    LCD_WriteData(ch);
}

void LCD_ShowStr(unsigned char x, unsigned char y, unsigned char *str) {
    LCD_SetCursor(x, y);
    while(*str != &#039;\0&#039;) {
        LCD_WriteData(*str);
        str++;
    }
}
提供了光标定位和显示字符/字符串的函数。
密码显示专用函数
void LCD_AddStar(void) {
    if(g_inputPos &lt; 16) {
        LCD_ShowChar(g_inputPos, 1, &#039;*&#039;);
        g_inputPos++;
    }
}

void LCD_DelStar(void) {
    if(g_inputPos &gt; 0) {
        g_inputPos--;
        LCD_ShowChar(g_inputPos, 1, &#039; &#039;);
        LCD_SetCursor(g_inputPos, 1);
    }
}
这两个函数用于在LCD第二行显示密码星号，并维护当前输入位置g_inputPos。每输入一位显示一个*，退格则清除最后一个星号。
矩阵键盘驱动
键盘扫描
unsigned char Keypad_Scan(void) {
    unsigned char col, key_value = KEY_NONE;
    unsigned char temp;
    // 逐行扫描
    KEYPAD_PORT = 0xFE; // 第一行输出低电平
    temp = KEYPAD_PORT &amp; 0xF0;
    if(temp != 0xF0) {
        // 消抖后读取列值
        ...
    }
    // 类似处理第二行(0xFD)、第三行(0xFB)、第四行(0xF7)
    ...
    return key_value;
}

4行（输出）：通过 KEYPAD_PORT 低4位控制，依次拉低某一行，其余行置高；
4列（输入）：通过 KEYPAD_PORT 高4位检测，若某列被拉低，说明对应行列交叉处的按键按下。

函数中按键编码与行列的对应关系（4行×4列=16个按键）：













































行号行控制值（KEYPAD_PORT）列0（0xE0）列1（0xD0）列2（0xB0）列3（0x70）第1行0xFE（二进制11111110）按键0按键1按键2按键3第2行0xFD（二进制11111101）按键4按键5按键6按键7第3行0xFB（二进制11111011）按键8按键9按键10按键11第4行0xF7（二进制11110111）按键12按键13按键14按键15

以第一行为例子
// 扫描第一行
KEYPAD_PORT = 0xFE;  // 拉低第1行（低4位第0位为0），其余行置高
temp = KEYPAD_PORT;
temp &amp;= 0xF0;        // 仅保留高4位（列输入值），屏蔽低4位（行输出值）

if(temp != 0xF0) {   // 高4位不全为1 → 有列被拉低 → 可能有按键按下
    LCD_Delay(10);   // 10ms消抖：过滤机械按键的抖动干扰
    temp = KEYPAD_PORT &amp; 0xF0;  // 消抖后再次读取列值

    if(temp != 0xF0) {  // 再次确认有按键按下（排除抖动）
        // 根据列值判断具体列号
        switch(temp) {
            case 0xE0: col = 0; break;  // 高4位1110 → 第0列按下
            case 0xD0: col = 1; break;  // 高4位1101 → 第1列按下
            case 0xB0: col = 2; break;  // 高4位1011 → 第2列按下
            case 0x70: col = 3; break;  // 高4位0111 → 第3列按下
            default: return KEY_NONE;   // 异常值，直接返回无按键
        }
        // 计算按键编码：第1行基准值0 + 列号
        key_value = 0 + col;
    }
}
后续三行仅行号基准值、编码不同
带消抖的按键获取
unsigned char Keypad_GetKey(void) {
    unsigned char currentKey = Keypad_Scan();
    if(currentKey != KEY_NONE) {
        if(g_lastKey == KEY_NONE) {
            g_lastKey = currentKey; // 第一次检测到，记录但不返回
            return KEY_NONE;
        }
        else if(g_lastKey == currentKey) {
            return currentKey;       // 连续两次相同，确认按键
        }
    }
    else {
        g_lastKey = KEY_NONE;        // 无按键，重置
    }
    return KEY_NONE;
}
实现简单的按键消抖：只有当连续两次扫描到同一个按键时才认为有效，返回键值。这样可以避免机械抖动造成的误触发。
长按检测
void UpdateKeyDisplay(void) {
    static unsigned char lastScanKey = KEY_NONE;
    static unsigned int keyHoldTime = 0;
    unsigned char currentScanKey = Keypad_Scan();

    if(currentScanKey != lastScanKey) {
        lastScanKey = currentScanKey;
        keyHoldTime = 0;
    } else if(currentScanKey != KEY_NONE) {
        keyHoldTime++;
        if(keyHoldTime &gt; 100) {          // 长按约1秒（假设主循环10ms）
            if(currentScanKey == KEY_OK) {
                // 进入修改密码模式
                g_systemState = STATE_CHANGE_PASSWORD;
                ...
            }
        }
    } else {
        lastScanKey = KEY_NONE;
        keyHoldTime = 0;
    }
}
UpdateKeyDisplay函数在主循环中频繁调用，用于检测按键长按事件。当检测到KEY_OK（通常是#键）长按超过100个循环（约1秒）时，系统切换到修改密码状态。
LED和蜂鸣器控制
void AlarmShort(void) {
    unsigned int i;
    for(i = 0; i &lt; 500; i++) {
        BUZZER = ~BUZZER;
        DelayMS(1);
    }
    BUZZER = 0;
}
短报警：蜂鸣器以1ms间隔翻转，持续500次，即产生约1秒的1kHz方波声音。
void AlarmLong(void) {
    unsigned int i;
    for(i = 0; i &lt; 1500; i++) {
        BUZZER = ~BUZZER;
        DelayMS(1);
    }
    BUZZER = 0;
}
长报警：持续3秒，用于锁定警告。
void LED_Flashing(unsigned char times, unsigned int interval) {
    unsigned char i;
    for(i = 0; i &lt; times; i++) {
        ALL_LED_ON();
        DelayMS(interval);
        ALL_LED_OFF();
        DelayMS(interval);
    }
}
LED闪烁效果，用于提示密码修改成功。
系统核心函数
重置输入缓冲区
void ResetInputBuffer(void) {
    unsigned char i;
    for(i = 0; i &lt; 4; i++) {
        g_inputBuffer[i] = 0;
    }
    g_inputIndex = 0;
    LCD_ResetPasswordDisplay();
}
清除输入缓冲区，并将LCD上的星号清除
密码验证与比较
unsigned char CheckPassword(void) {
    unsigned char i;
    for(i = 0; i &lt; 4; i++) {
        if(g_inputBuffer[i] != g_password[i]) {
            return 0;
        }
    }
    return 1;
}

void CopyPassword(unsigned char *dest, unsigned char *src) {
    unsigned char i;
    for(i = 0; i &lt; 4; i++) {
        dest[i] = src[i];
    }
}

unsigned char ComparePassword(unsigned char *pwd1, unsigned char *pwd2) {
    unsigned char i;
    for(i = 0; i &lt; 4; i++) {
        if(pwd1[i] != pwd2[i]) {
            return 0;
        }
    }
    return 1;
}
简单的数组比较和复制函数。
状态机处理函数- main
void main(void) {
    // 初始化所有模块
    LCD_Init();
    Keypad_Init();
    LED_Buzzer_Init();

    // 显示欢迎信息
    LCD_ShowStr(0, 0, &quot;Electronic Lock&quot;);
    LCD_ShowStr(0, 1, &quot;System Ready&quot;);
    // 【删除】移除了 DisplayKeyValue(KEY_NONE);

    DelayS(2);

    // 主循环
    while(1) {
        switch(g_systemState) {
            case STATE_INPUT_PASSWORD:
                StateInputPassword();
                break;

            case STATE_VERIFY_PASSWORD:
                StateVerifyPassword();
                break;

            case STATE_LOCKED:
                StateLocked();
                break;

            case STATE_CHANGE_PASSWORD:
                StateChangePassword();
                break;

            default:
                g_systemState = STATE_INPUT_PASSWORD;
                break;
        }

        DelayMS(10);
    }
}
上电后首先执行硬件模块初始化，为系统运行做准备：

LCD1602 初始化
按键矩阵初始化
LCD1602 初始化
然后显示欢迎界面

// 显示欢迎信息
LCD_ShowStr(0, 0, &quot;Electronic Lock&quot;);
LCD_ShowStr(0, 1, &quot;System Ready&quot;);
DelayS(2);
然后进入状态机主循环
系统有四个状态，每个状态对应一个处理函数，它们会在主循环中被调用。状态之间通过修改g_systemState进行切换。
状态0：输入密码- StateInputPassword

显示提示”Enter Password:“，第二行等待输入。
循环扫描按键：

数字键（0-9）：如果输入未满4位，存入缓冲区并显示星号。
退格键（KEY_BACK）：删除最后一位。
确认键（KEY_OK）：当输入满4位时，切换到状态3（验证密码）。
星号键（KEY_STAR）：直接进入状态1（修改密码），不需要长按。


同时不断调用UpdateKeyDisplay检测长按事件（长按OK也可进入修改密码）。

状态3：验证密码- StateVerifyPassword

调用CheckPassword比较输入和存储密码。
若正确：

显示”Correct! Welcome!”
绿灯亮1秒
错误计数清零


若错误：

显示”Error! Try Again!”
红灯亮1秒，蜂鸣器短鸣
错误计数加1
如果错误次数达到3次，切换到状态2（锁定）


最后重置输入缓冲区，返回状态0（输入密码）。

状态2：锁定- StateLocked

显示”LOCKED! Wait 3 sec”
蜂鸣器长鸣3秒
延时3秒（实际通过循环DelayS实现）
重置错误计数和输入缓冲区，返回状态0。

状态1：修改密码- StateChangePassword
这个状态较为复杂，分为两个阶段：

第一阶段（第一次输入）：显示”New Password:“，用户输入4位新密码，按OK后存入g_newPassword，然后清屏显示”Input Again:“，进入第二阶段。
第二阶段（第二次确认）：用户再次输入4位密码，按OK后与g_newPassword比较：

如果一致，则更新g_password为新密码，显示”Password Changed!”，LED闪烁3次，延时1秒后返回状态0。
如果不一致，显示”Not Match! Try Again”，短鸣，然后返回第一阶段重新输入。


任何时候可按退格键删除，按OK确认（输入满4位才有效）。
在修改密码过程中，长按OK检测仍然有效，但此时系统已在修改状态，不会重复进入。

代码小记/vim批量处理小记.content:
﻿# 引入
前段时间考马原
舍友给了题库的word文档，
文档里面是题目和答案一并给出的
想把答案遮住，点开才能看的形式，这样复习会更加高效一点
怎么做呢，第一时间想到的是用vim

vim给我的首印象就是能做到更加灵活的全局搜索替换

解决


首先观察到文件里面近乎所有的答案行都包含了“正确答案”这一关键字
在“正确答案”和 “:C”之间插入部分html代码，得到
&lt;details&gt;&lt;summary&gt;正确答案&lt;/summary&gt;：C&lt;/details&gt;
即可实现对答案隐藏


在“正确答案”前插入&lt;details&gt;&lt;summary&gt;，在“正确答案”后插入&lt;/summary&gt;


:%s/^\(.*正确答案：\)/&lt;details&gt;&lt;summary&gt;\1&lt;\/summary&gt;/g

解释：

:%s：表示全局替换。
^(.*正确答案：)：匹配每行开头到“正确答案：”部分，将其捕获到分组 \1 中。
&lt;details&gt;&lt;summary&gt;\1&lt;\/summary&gt;：在匹配内容前增加 &lt;details&gt;&lt;summary&gt;，并在“正确答案：”后增加 &lt;/summary&gt;。
g：全局替换。



在每个含有“正确答案：”的行末尾追加 &lt;/details&gt;：

:%s/\(正确答案：.*\)$/\1&lt;\/details&gt;/g

解释：

(正确答案：.*)$：匹配“正确答案：”及其后所有内容，将其捕获到分组 \1 中。
\1&lt;/details&gt;：在匹配内容末尾追加 &lt;/details&gt;。


实现效果))
追加
线上题库测试本来说要在考试前两天关闭，我那会刷的还不多，本来想配合这个能隐藏答案的文档写一个能随机出题的程序来着，但是文件处理这块貌似来不及学，在考前再浪费时间就有点得不偿失，就简单写了个抽取随机数对应这个文档的题号的c。
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;time.h&gt;

#define TOTAL_SINGLE 40
#define TOTAL_MULTIPLE 20
#define TOTAL_TRUE_FALSE 20
#define MAX_CHAPTERS 8

// 各章节的题目数量
const int singleCounts[MAX_CHAPTERS] = {26, 188, 117, 117, 145, 32, 45, 22};
const int multipleCounts[MAX_CHAPTERS] = {26, 106, 119, 116, 87, 76, 59, 27};
const int trueFalseCounts[MAX_CHAPTERS] = {18, 114, 77, 54, 43, 50, 37, 49};

// 记录得分
int score = 0;

// 随机生成一个题目
void generateQuestion(int type, int chapter, int question, int currentIndex) {
    const char *typeStr;
    if (type == 1) typeStr = &quot;dan&quot;; // 单选
    else if (type == 2) typeStr = &quot;duo&quot;; // 多选
    else typeStr = &quot;pan&quot;; // 判断

    printf(&quot;试卷第%d题: %d.%s.%d\n&quot;, currentIndex, chapter, typeStr, question);
}

// 从某个题库中随机抽取题目
int getRandomQuestion(int totalQuestions) {
    return rand() % totalQuestions + 1;
}

int main() {
    srand(time(NULL)); // 初始化随机种子

    int usedSingle = 0, usedMultiple = 0, usedTrueFalse = 0;
    int selectedChapters[MAX_CHAPTERS] = {0}; // 用于记录抽取的章节

    printf(&quot;随机试卷生成开始\n\n&quot;);

    int currentIndex = 1; // 当前是第几题

    // 随机生成单选题
    for (int i = 0; i &lt; TOTAL_SINGLE; i++, currentIndex++) {
        int chapter = rand() % MAX_CHAPTERS; // 随机选择章节
        int question = getRandomQuestion(singleCounts[chapter]);
        generateQuestion(1, chapter, question, currentIndex);

        printf(&quot;请输入答案是否正确(1错误/2正确，3提前交卷): &quot;);
        int isCorrect;
        scanf(&quot;%d&quot;, &amp;isCorrect);

        if (isCorrect == 3) {
            printf(&quot;提前交卷，未作答的题目将按错误处理。\n&quot;);
            goto finish;
        }

        if (isCorrect == 2) score += 1; // 单选题每题1分
    }

    // 随机生成多选题
    for (int i = 0; i &lt; TOTAL_MULTIPLE; i++, currentIndex++) {
        int chapter = rand() % MAX_CHAPTERS; // 随机选择章节
        int question = getRandomQuestion(multipleCounts[chapter]);
        generateQuestion(2, chapter, question, currentIndex);

        printf(&quot;请输入答案是否正确(1错误/2正确，3提前交卷): &quot;);
        int isCorrect;
        scanf(&quot;%d&quot;, &amp;isCorrect);

        if (isCorrect == 3) {
            printf(&quot;提前交卷，未作答的题目将按错误处理。\n&quot;);
            goto finish;
        }

        if (isCorrect == 2) score += 2; // 多选题每题2分
    }

    // 随机生成判断题
    for (int i = 0; i &lt; TOTAL_TRUE_FALSE; i++, currentIndex++) {
        int chapter = rand() % MAX_CHAPTERS; // 随机选择章节
        int question = getRandomQuestion(trueFalseCounts[chapter]);
        generateQuestion(3, chapter, question, currentIndex);

        printf(&quot;请输入答案是否正确(1错误/2正确，3提前交卷): &quot;);
        int isCorrect;
        scanf(&quot;%d&quot;, &amp;isCorrect);

        if (isCorrect == 3) {
            printf(&quot;提前交卷，未作答的题目将按错误处理。\n&quot;);
            goto finish;
        }

        if (isCorrect == 2) score += 1; // 判断题每题1分
    }

finish:
    // 剩余未答题按错误处理
    score += (TOTAL_SINGLE + TOTAL_MULTIPLE + TOTAL_TRUE_FALSE - currentIndex + 1) * 0;

    printf(&quot;\n试卷完成，您的总得分是: %d 分\n&quot;, score);

    return 0;
}


效果)


