void Quick_Sort(int *arr, int begin, int end)//快速排序,升序
{
    if(begin &gt; end)//只有一个数，基准确定，递归的出口
        return;
    int tmp = arr[begin];
    int i = begin;
    int j = end;
    while(i != j){
        while(arr[j] &gt;= tmp &amp;&amp; j &gt; i)
            j--;
        while(arr[i] &lt;= tmp &amp;&amp; j &gt; i)
            i++;
        if(j &gt; i){
            int t = arr[i];
            arr[i] = arr[j];
            arr[j] = t;
        }
    }
    arr[begin] = arr[i];
    arr[i] = tmp;
    Quick_Sort(arr, begin, i-1);//递归，对基准数的左边进行相同操作
    Quick_Sort(arr, i+1, end);//递归，对基准数的右边进行相同操作
