int search(int* nums, int numsSize, int target){
    int i=0,j=numsSize-1;
    while(i&lt;=j)
    {
        int temp=i+(j-i)/2;
        if(nums[temp]==target)return temp;
        else if(nums[temp]&gt;target)
        {
            j=temp-1;
        }
        else if(nums[temp]&lt;target)
        {
            i=temp+1;
        }
    }
    return -1;  
