//假设要读取所有的外设的数据到缓冲区
void read_device_revdto_buff()
{
    int size= sizeof(devices)/sizeof(devices[0]);
    char buff[4096];
    for (int i=0;i&lt;size;i++)
    {
        //上层不需要知道具体做了什么
        //隐藏具体外设的敏感信息，达到很好的扩展性
        devices[i].open(NULL);
        devices[i].read(buff);
        devices[i].write(buff);
        devices[i].close();
    }
}
int main(void)
{
    reead_device_revdto_buff();//有良好的抽象性和扩展性
    return 0;
}
